mapper.sql:
WHERE 1 = 1

   AND T1.GUID = #{guid}


   AND T1.SERVICE_ID LIKE '%' || #{serviceId} || '%'


   AND T1.SCREEN_ID LIKE '%' || #{screenId} || '%'


   AND T1.OPTR_ENO = #{optrEno}


   AND T1.EXCEPTION_TYPE IS NOT NULL


   AND T1.REQUEST_TIME >= #{requestTimeFrom}


   AND T1.REQUEST_TIME <= #{requestTimeTo}


   AND T1.REQUEST_TIME IS NOT NULL
   AND T1.RESPONSE_TIME IS NOT NULL
   AND LENGTH(T1.REQUEST_TIME) >= 14
   AND LENGTH(T1.RESPONSE_TIME) >= 14
   AND (TO_DATE(SUBSTR(T1.RESPONSE_TIME, 1, 14), 'YYYYMMDDHH24MISS')
      - TO_DATE(SUBSTR(T1.REQUEST_TIME, 1, 14), 'YYYYMMDDHH24MISS')) * 86400
       >= #{minElapsedSeconds}

mapper.delete:
DELETE /* mgcoa8888D0_D0 */ FROM TB_FW_IMAGE_LOG
 WHERE GUID IN

    #{guid}
